import{_ as a,o as t,c as n,a0 as s}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Follow along: uploading attachments, referencing images and downloading","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/attachments"},"headers":[],"relativePath":"en/tutorials/attachments.md","filePath":"en/tutorials/attachments.md"}'),i={name:"en/tutorials/attachments.md"};function o(r,e,d,l,c,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="follow-along-uploading-attachments-referencing-images-and-downloading" tabindex="-1">Follow along: uploading attachments, referencing images and downloading <a class="header-anchor" href="#follow-along-uploading-attachments-referencing-images-and-downloading" aria-label="Permalink to &quot;Follow along: uploading attachments, referencing images and downloading&quot;">​</a></h1><p><code>just dev</code> now starts PostgreSQL and RustFS, runs database migrations, and initializes browser CORS for a dedicated private bucket. The first run pulls pinned image versions; the API/Web keep the original development feedback loop.</p><p>Save a document, pick a file under &quot;附件&quot; (Attachments) and click &quot;上传附件&quot; (Upload attachment). The page shows preparing, upload progress and verification states; the attachment enters the list only after verification passes. Each row carries a file-type icon: the image and document icons come from a vendored Material Symbols subset (with its license file, removed together with the knowledge example), while general action icons remain Lucide. Clicking download returns the original bytes; images can be referenced from the edit page via &quot;插入引用&quot; (Insert reference), viewed by switching to the preview, then saved explicitly. The design system&#39;s &quot;场景&quot; (Scenes) tab includes &quot;附件图标与上传状态&quot; (Attachment icons and upload states), which demos these file icons and the upload lifecycle feedback offline on demo data without creating real files.</p><p>The defaults are a 20 MiB per-file limit, a 15-minute upload session and 60-second download links. The actual values come from the <a href="./../reference/config">generated configuration reference</a>; changing the frontend hint alone does nothing.</p><h2 id="_1-the-browser-receives-a-limited-capability" tabindex="-1">1. The browser receives a limited capability <a class="header-anchor" href="#_1-the-browser-receives-a-limited-capability" aria-label="Permalink to &quot;1. The browser receives a limited capability&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/apps/web/src/knowledge-files.ts" target="_blank" rel="noreferrer">web file adapter</a> reads the File, computes SHA-256, reports XHR upload progress and performs the actual download. The app&#39;s cookies are used only for its own API and are omitted for S3 transfers. A single byte transfer gets at most 120 seconds (including reading the response body); after a timeout the retry action recovers, and leaving the page cancels the transfer.</p><p>An upload request sends the file name, MIME type, size and checksum. The server verifies document edit rights, generates a staging key, records the upload and its business association, and returns the URL, method, required headers and deadline. The frontend cannot choose the bucket or key and never sees the storage admin credentials. The original file name is a display value only; it is never used as an object path.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/crates/platform/src/object_storage.rs" target="_blank" rel="noreferrer">ObjectStorage adapter</a> uses the standard S3 API with pinned RustFS 1.0.0 and AWS SDK 1.149.0. Internal operation endpoints and the public signing endpoint are separate: requests are signed against the public address, and the hostname or path is never rewritten afterwards. Signatures bind the content type, checksum header and upload identity; Content-Encoding is fixed to identity so downloads never change the bytes through content decoding. The browser-controlled Content-Length is not part of the returned headers.</p><p>The dedicated bucket is private by default. Initialization creates it only when HEAD confirms a 404, never treating 403 as absence; the idempotent initialization uses bounded standard retries that cover the observed concurrent CreateBucket <code>503 SlowDown</code>. Conditional copies keep a single attempt; timeouts are handled through candidate records.</p><h2 id="_2-uploaded-to-storage-does-not-mean-published" tabindex="-1">2. Uploaded to storage does not mean published <a class="header-anchor" href="#_2-uploaded-to-storage-does-not-mean-published" aria-label="Permalink to &quot;2. Uploaded to storage does not mean published&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer">Core Files</a> owns file state and candidate object records; the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/crates/app/src/modules/knowledge/attachments.rs" target="_blank" rel="noreferrer">knowledge attachment use case</a> owns the document association and base-level authorization. Core never reads the Document or Grant tables.</p><p>Completion runs in three phases:</p><ol><li>A short transaction re-verifies document edit rights, registers the unique candidate key first, then commits.</li><li>Outside the transaction, the staged object&#39;s ETag is read and conditionally copied to the exclusive candidate key; the candidate&#39;s actual length, MIME/upload identity, full bytes and SHA-256 are then checked.</li><li>The current credentials, document existence, Grant, upload state and deadline are verified again; then the single ready object is selected atomically, the attachment associated and the Audit written.</li></ol><p>The candidate copy conditions on both the source ETag and <code>If-None-Match: *</code> on the target. After publication nothing writes to that key again; an old upload URL only ever acts on the staged object. When two completion requests race, one candidate wins and the other requests resolve to the same attachment.</p><p>Images and PDFs get an extra file-identity check; other types are verified on download against the declared MIME and the full bytes. This template does no general document parsing or malware scanning, and uploaded HTML is never executed as a trusted application page.</p><h2 id="_3-retries-and-failures" tabindex="-1">3. Retries and failures <a class="header-anchor" href="#_3-retries-and-failures" aria-label="Permalink to &quot;3. Retries and failures&quot;">​</a></h2><p>Creating an upload resource uses an Idempotency-Key and records a stable upload_id. Short-lived URLs are regenerated on each re-authorization, with deadlines inside the upload session. Network failures can retry the same resource; an expired or rejected upload says so explicitly and restarts from a new resource.</p><p>Size/type mismatches never publish; revocation, an expired auth session or a vanished source document also block the final commit. When the audit write fails, the ready state and the attachment association roll back together, and completion can be retried afterwards.</p><p>Every candidate has a durable record before any I/O. A copy timeout may already have succeeded remotely; failed candidates and their staging locations are never forgotten, and the later cleanup chapter handles expired, rejected and deleted objects. A single Delete or SDK timeout is never proof that &quot;no late object can appear&quot;.</p><h2 id="_4-short-lived-downloads-and-markdown-references" tabindex="-1">4. Short-lived downloads and Markdown references <a class="header-anchor" href="#_4-short-lived-downloads-and-markdown-references" aria-label="Permalink to &quot;4. Short-lived downloads and Markdown references&quot;">​</a></h2><p>Only ready attachments still associated with a visible document can mint new download links. Readers can download, Editors can upload; after revocation no new links can be requested, but already-issued links may stay valid until they expire, and transfers already accepted may finish. That is the explicit permission boundary of this direct-download model.</p><p>Downloads default to attachment disposition, no-store and safe file-name encoding. The web adapter verifies the length and saves the payload as a binary file; the temporary Blob URL is released afterwards.</p><p>Markdown stores <code>attachment:&lt;attachment ID&gt;</code> — never a presigned URL or a permanent public address. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/packages/views/src/knowledge/attachment-markdown.tsx" target="_blank" rel="noreferrer">Markdown attachment renderer</a> validates the reference format, then requests an access capability from the API for the current document and member. Only common bitmaps that pass the checks render inline; other attachments get a download action, and arbitrary remote images still never load automatically.</p><h2 id="_5-from-the-local-configuration-to-your-deployment" tabindex="-1">5. From the local configuration to your deployment <a class="header-anchor" href="#_5-from-the-local-configuration-to-your-deployment" aria-label="Permalink to &quot;5. From the local configuration to your deployment&quot;">​</a></h2><p>The local <code>.env.example</code> ships development-only RustFS credentials. The key settings are:</p><ul><li><code>S3_ENDPOINT</code>: the internal S3 root used by the API/Worker; when unset the file capability turns off while text and auth keep working.</li><li><code>S3_PUBLIC_ENDPOINT</code>: the separate S3 origin the browser can reach; production uses HTTPS and does not mount it under a path-rewriting subdirectory.</li><li><code>S3_BUCKET / S3_REGION / S3_ACCESS_KEY / S3_SECRET_KEY</code>: the dedicated bucket and explicit server-side credentials.</li><li><code>FILE_MAX_BYTES / UPLOAD_SESSION_SECS / DOWNLOAD_URL_SECS</code>: the actual upload and signing boundaries.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap-storage</span></span></code></pre></div><p>The initialization command loads <code>.env.example</code> / <code>.env</code> and the process environment like <code>just dev</code>, and configures the dedicated bucket&#39;s CORS through the application settings. The RustFS data and log named volumes must be writable by UID/GID 10001; <code>/health/ready</code> decides readiness. <code>Ctrl+C</code> stops the API/Web and keeps the data volumes.</p><h2 id="_6-verifying-the-same-path" tabindex="-1">6. Verifying the same path <a class="header-anchor" href="#_6-verifying-the-same-path" aria-label="Permalink to &quot;6. Verifying the same path&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-storage.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attachments</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/attachments.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>The storage tests connect to a real RustFS and cover deadlines and signing headers, bad checksums, byte reads, source/target copy conditions and concurrent initialization. The HTTP tests connect to a real database and storage and cover staging invisibility, unique publication, replay, deadlines, size/type, audit rollback, Reader/Editor, cross-document references, plus revocation/session-expiry/source-disappearance during the copy.</p><p>View tests drive the real page with WebCrypto and an HTTP boundary: upload progress, resource reuse after failure, the size limit, read-only access, reference insertion and safe image URLs, and every attachment row carrying a file-type icon with an accessible name. The design-system test walks the &quot;附件图标与上传状态&quot; (Attachment icons and upload states) scene: the icon gallery and the uploading, done and failed states on demo data. After finishing a key journey, run once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/attachments.spec.ts</span></span></code></pre></div><p>The browser uploads a real image, compares bytes after download, then saves an attachment reference and reloads the preview. The default feedback loop does not re-run the browser journey.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">ownership manifest</a> ties attachment associations, business routes, Views, web wiring and the tutorials to the knowledge example; Core Files, the S3 adapter, the general configuration and the isolated test runners stay behind for your own business.</p><hr><p>Source version：<code>da17f6123c09</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/docs/tutorials/09-attachments.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,37)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
